def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result") or {}
    outcome = result.get("outcome")
    credit_limit = int(result.get("credit_limit") or 0)

    if outcome == "declined":
        return {"action": "decline", "limit": 0}

    if outcome == "approved":
        # Network referral rule: self_employed with requested_limit strictly > 4000
        # must be queue_review instead of issued. Applies only to approved outcomes.
        if app.get("employment") == "self_employed" and int(app.get("requested_limit") or 0) > 4000:
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": credit_limit}

    # manual_review (or any other non-approve outcome) -> queue_review
    return {"action": "queue_review", "limit": 0}

